import { desc, sql } from "drizzle-orm";
import {
  check,
  date,
  index,
  integer,
  pgTable,
  smallint,
  text,
  timestamp,
} from "drizzle-orm/pg-core";

import { DONENESS_VALUES } from "@/lib/sightings";

const DONENESS_CONSTRAINT_VALUES = sql.raw(
  DONENESS_VALUES.map((value) => `'${value}'`).join(", ")
);

export const sightings = pgTable(
  "sightings",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    labelDate: date("label_date", { mode: "string" }).notNull(),
    labelMinute: smallint("label_minute").notNull(),
    doneness: text({ enum: DONENESS_VALUES }),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [
    check(
      "sightings_label_minute_check",
      sql`${table.labelMinute} between 0 and 1439`
    ),
    check(
      "sightings_doneness_check",
      sql`${table.doneness} in (${DONENESS_CONSTRAINT_VALUES})`
    ),
    index("sightings_recent_idx").on(desc(table.createdAt), desc(table.id)),
  ]
);

export const schema = { sightings };

export type Sighting = typeof sightings.$inferSelect;
import { eq } from "drizzle-orm";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";

import { db } from "@/lib/db";
import { type schema, sightings } from "@/lib/db/schema";
import {
  type CreateSighting,
  type CreateSightingInput,
  type CreateSightingResult,
  DONENESS_FAILURE_MESSAGE,
  SAVE_FAILURE_MESSAGE,
  type UpdateSightingDoneness,
  type UpdateSightingDonenessInput,
  type UpdateSightingDonenessResult,
} from "@/lib/sightings";

type Database = NodePgDatabase<typeof schema>;

export function createSightingOperations(database: Database): {
  create: CreateSighting;
  updateDoneness: UpdateSightingDoneness;
} {
  return {
    create: async (
      input: CreateSightingInput
    ): Promise<CreateSightingResult> => {
      try {
        const [record] = await database
          .insert(sightings)
          .values(input)
          .returning();

        if (!record) {
          return { message: SAVE_FAILURE_MESSAGE, ok: false };
        }

        return { ok: true, sighting: record };
      } catch {
        return { message: SAVE_FAILURE_MESSAGE, ok: false };
      }
    },
    updateDoneness: async (
      input: UpdateSightingDonenessInput
    ): Promise<UpdateSightingDonenessResult> => {
      try {
        const [record] = await database
          .update(sightings)
          .set({ doneness: input.doneness, updatedAt: new Date() })
          .where(eq(sightings.id, input.id))
          .returning();

        if (!record) {
          return {
            kind: "not-found",
            message: "This sighting is no longer available.",
            ok: false,
          };
        }

        return { ok: true, sighting: record };
      } catch {
        return {
          kind: "unavailable",
          message: DONENESS_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
  };
}

export const sightingOperations = createSightingOperations(db);
import { createServerFn } from "@tanstack/react-start";

import {
  createSightingInputSchema,
  updateSightingDonenessInputSchema,
} from "@/lib/sightings";

export const saveSighting = createServerFn({ method: "POST" })
  .inputValidator(createSightingInputSchema)
  .handler(async ({ data }) => {
    const { sightingOperations } = await import("@/lib/sightings.server");

    return sightingOperations.create(data);
  });

export const updateSightingDoneness = createServerFn({ method: "POST" })
  .inputValidator(updateSightingDonenessInputSchema)
  .handler(async ({ data }) => {
    const { sightingOperations } = await import("@/lib/sightings.server");

    return sightingOperations.updateDoneness(data);
  });

